function sipFuture(monthly, annualRatePct, years, initial){
  monthly=+monthly; var r=+annualRatePct/100/12; var N=Math.round(+years*12); initial=+initial||0;
  if(!(monthly>=0)||!(years>0)) return {error:'月投与年限须为正'};
  var fvInit = initial*Math.pow(1+r,N);
  var fvAnnu = (r===0) ? monthly*N : monthly*((Math.pow(1+r,N)-1)/r)*(1+r);
  var fv = fvInit + fvAnnu;
  var invested = initial + monthly*N;
  return {fv:Math.round(fv), invested:Math.round(invested), gain:Math.round(fv-invested), monthly:monthly, years:years}; }
var EXPORTS={sipFuture:sipFuture};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SipForgePure = EXPORTS; }
